import fs from 'fs';

/**
 * Функция-конструктор полной программы C++ из краткого тела решения
 */
function buildFullCpp(headers, body, extraFuncs = '') {
  const incs = headers.map((h) => `#include <${h}>`).join('\n');
  const funcBlock = extraFuncs ? `\n${extraFuncs}\n` : '';
  return `${incs}\nusing namespace std;\n${funcBlock}\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n${body.split('\n').join('\n    ')}\n    return 0;\n}`;
}

/**
 * Функция-конструктор шаблона initialCode для ученика
 */
function buildInitCpp(headers, hintComment) {
  const incs = headers.map((h) => `#include <${h}>`).join('\n');
  return `${incs}\nusing namespace std;\n\nint main() {\n    //${hintComment}\n    \n    return 0;\n}`;
}

