    theoryContent: `# Динамический массив std::vector

Контейнер \`std::vector<T>\` из заголовочного файла \`<vector>\` автоматически управляет памятью в куче.

### Основные методы:
- \`v.push_back(x)\` — добавить элемент \`x\` в конец за $O(1)$ амортизированно.
- \`v.pop_back()\` — удалить последний элемент.
- \`v.size()\` — текущее количество элементов.
- \`v.insert(v.begin() + pos, x)\` — вставка по индексу \`pos\`.
- \`v.erase(v.begin() + pos)\` — удаление элемента с индексом \`pos\`.`,
    headers: ['iostream', 'vector'],
    tasks: [
      ['Фильтрация только чётных в вектор', 'Дано $N$ и $N$ целых чисел. Соберите все чётные числа в `std::vector` и выведите его размер.', 'int n; cin >> n; vector<int> v; for (int i = 0; i < n; ++i) { int x; cin >> x; if (x % 2 == 0) v.push_back(x); } cout << v.size() << "\\n";', [['5\n1 2 3 4 6', '3'], ['3\n1 3 5', '0'], ['4\n2 4 8 10', '4']]],
      ['Удаление элемента по индексу K', 'Дано $N$, массив из $N$ чисел и индекс $K$ ($0 \\le K < N$). Удалите элемент с индексом $K$ через `erase` и выведите оставшиеся через пробел.', 'int n; cin >> n; vector<int> v(n); for (int i = 0; i < n; ++i) cin >> v[i]; int k; cin >> k; v.erase(v.begin() + k); for (size_t i = 0; i < v.size(); ++i) cout << v[i] << (i + 1 < v.size() ? " " : ""); cout << "\\n";', [['4\n10 20 30 40\n1', '10 30 40'], ['3\n5 6 7\n0', '6 7'], ['3\n1 2 3\n2', '1 2']]],
      ['Вставка элемента на позицию K', 'Дано $N$, массив из $N$ чисел, затем индекс $K$ и число $X$. Вставьте $X$ на позицию $K$ методом `insert` и выведите вектор.', 'int n; cin >> n; vector<int> v(n); for (int i = 0; i < n; ++i) cin >> v[i]; int k, x; cin >> k >> x; v.insert(v.begin() + k, x); for (size_t i = 0; i < v.size(); ++i) cout << v[i] << (i + 1 < v.size() ? " " : ""); cout << "\\n";', [['3\n10 20 30\n1 99', '10 99 20 30'], ['2\n1 2\n0 5', '5 1 2'], ['2\n7 8\n2 9', '7 8 9']]],
      ['Объединение двух векторов', 'Дано $N$ и первый вектор, затем $M$ и второй вектор. Допишите элементы второго в конец первого и выведите результат.', 'int n; cin >> n; vector<int> a(n); for (int i = 0; i < n; ++i) cin >> a[i]; int m; cin >> m; for (int i = 0; i < m; ++i) { int x; cin >> x; a.push_back(x); } for (size_t i = 0; i < a.size(); ++i) cout << a[i] << (i + 1 < a.size() ? " " : ""); cout << "\\n";', [['2\n1 2\n3\n3 4 5', '1 2 3 4 5'], ['1\n10\n1\n20', '10 20'], ['2\n7 8\n2\n1 2', '7 8 1 2']]],
      ['Префиксные суммы в векторе', 'Дано $N$ и массив $A$. Постройте вектор префиксных сумм $P$, где $P[i] = A[0] + \\dots + A[i]$, и выведите его.', 'int n; cin >> n; long long cur = 0; for (int i = 0; i < n; ++i) { long long x; cin >> x; cur += x; cout << cur << (i + 1 < n ? " " : ""); } cout << "\\n";', [['4\n1 2 3 4', '1 3 6 10'], ['3\n5 -2 7', '5 3 10'], ['2\n10 20', '10 30']]],
      ['Сжатие подряд идущих дубликатов', 'Дано $N$ и $N$ чисел. Добавляйте число в вектор только в том случае, если оно не равно предыдущему добавленному. Выведите итоговый вектор.', 'int n; cin >> n; vector<int> v; for (int i = 0; i < n; ++i) { int x; cin >> x; if (v.empty() || v.back() != x) v.push_back(x); } for (size_t i = 0; i < v.size(); ++i) cout << v[i] << (i + 1 < v.size() ? " " : ""); cout << "\\n";', [['6\n1 1 2 2 2 3', '1 2 3'], ['4\n5 5 5 5', '5'], ['5\n1 2 1 2 1', '1 2 1 2 1']]],
      ['Разность соседних элементов', 'Дано $N \\ge 2$ и вектор $A$. Выведите через пробел $N-1$ чисел: $A[1]-A[0], A[2]-A[1], \\dots$', 'int n; cin >> n; vector<int> a(n); for (int i = 0; i < n; ++i) cin >> a[i]; for (int i = 1; i < n; ++i) cout << a[i] - a[i - 1] << (i + 1 < n ? " " : ""); cout << "\\n";', [['4\n10 15 12 20', '5 -3 8'], ['3\n1 2 3', '1 1'], ['2\n5 5', '0']]],
      ['Обмен минимума и максимума', 'Дано $N$ и массив различных чисел. Поменяйте местами минимальный и максимальный элементы и выведите вектор.', 'int n; cin >> n; vector<int> a(n); int mn = 0, mx = 0; for (int i = 0; i < n; ++i) { cin >> a[i]; if (a[i] < a[mn]) mn = i; if (a[i] > a[mx]) mx = i; } swap(a[mn], a[mx]); for (int i = 0; i < n; ++i) cout << a[i] << (i + 1 < n ? " " : ""); cout << "\\n";', [['4\n10 2 8 20', '10 20 8 2'], ['3\n1 2 3', '3 2 1'], ['2\n9 1', '1 9']]],
      ['Количество локальных максимумов', 'Элемент называется локальным максимумом, если он строго больше обоих своих соседей. Подсчитайте их количество в векторе из $N$ чисел.', 'int n, cnt = 0; cin >> n; vector<int> a(n); for (int i = 0; i < n; ++i) cin >> a[i]; for (int i = 1; i + 1 < n; ++i) if (a[i] > a[i - 1] && a[i] > a[i + 1]) cnt++; cout << cnt << "\\n";', [['5\n1 5 2 6 3', '2'], ['4\n1 2 3 4', '0'], ['5\n1 3 1 3 1', '2']]],
      ['Перенос нулей в конец вектора', 'Дано $N$ и массив чисел. Переместите все нули в конец, сохранив относительный порядок ненулевых элементов.', 'int n; cin >> n; vector<int> res; int zeros = 0; for (int i = 0; i < n; ++i) { int x; cin >> x; if (x == 0) zeros++; else res.push_back(x); } while (zeros--) res.push_back(0); for (int i = 0; i < n; ++i) cout << res[i] << (i + 1 < n ? " " : ""); cout << "\\n";', [['5\n0 1 0 3 12', '1 3 12 0 0'], ['3\n0 0 1', '1 0 0'], ['3\n1 2 3', '1 2 3']]]
    ]
